import numpy as np
from itertools import combinations

try:
    from treehfd import XGBTreeHFD
except Exception:
    XGBTreeHFD = None


def _pair_scores(model, p):
    """Score pairs by gain-weighted co-occurrence along tree paths."""
    scores = {}
    try:
        df = model.get_booster().trees_to_dataframe()
    except Exception:
        return scores
    names = model.get_booster().feature_names

    def fidx(f):
        if f == "Leaf":
            return None
        if names is not None and f in names:
            return names.index(f)
        try:
            return int(str(f).lstrip("f"))
        except Exception:
            return None

    for _, t in df.groupby("Tree"):
        rows = {r["ID"]: r for _, r in t.iterrows()}
        def walk(nid, path):
            r = rows[nid]
            f = fidx(r["Feature"])
            if f is None:
                return
            g = float(r["Gain"])
            for (pf, pg) in path:
                if pf != f:
                    k = (min(pf, f), max(pf, f))
                    scores[k] = scores.get(k, 0.0) + min(pg, g)
            for c in (r["Yes"], r["No"]):
                if c in rows:
                    walk(c, path + [(f, g)])
        root = t[t["Node"] == 0]["ID"].iloc[0]
        walk(root, [])
    return scores


def _full(model, X_train, X_test, order=2, pairs=None):
    hfd = XGBTreeHFD(model)
    if pairs is not None:
        try:
            hfd.fit(X_train, interaction_order=order, interaction_list=np.array(pairs, dtype=int), verbose=False)
        except TypeError:
            hfd.fit(X_train, interaction_order=order, verbose=False)
    else:
        hfd.fit(X_train, interaction_order=order, verbose=False)
    return hfd


def decompose(model, X_train, X_test, top_k=None):
    p = X_train.shape[1]
    scores = _pair_scores(model, p)
    ranked = sorted(scores, key=lambda k: -scores[k])
    if top_k is None:
        top_k = max(1, min(len(ranked), max(p, 10)))
    keep = [tuple(int(v) for v in k) for k in ranked[:top_k]]
    keep = sorted(set(keep))

    if not keep:
        hfd = _full(model, X_train, X_test, order=1)
        y_main = hfd.predict(X_test, verbose=False)
        if isinstance(y_main, tuple):
            y_main = y_main[0]
        comps = {(j,): np.asarray(y_main[:, j]) for j in range(y_main.shape[1])}
        return float(hfd.eta0), comps

    hfd = _full(model, X_train, X_test, order=2, pairs=keep)
    y_main, y_o2 = hfd.predict(X_test, verbose=False)
    comps = {(j,): np.asarray(y_main[:, j]) for j in range(y_main.shape[1])}
    keepset = set(keep)
    for k, (a, b) in enumerate(hfd.interaction_list):
        a, b = int(a), int(b)
        if a > b:
            a, b = b, a
        if (a, b) in keepset:
            comps[(a, b)] = np.asarray(y_o2[:, k])
    return float(hfd.eta0), comps
